func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "nil width zero",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "nil width negative",
			text:  "hello world",
			width: -5,
			want:  nil,
		},
		{
			name:  "empty string",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace only",
			text:  "   ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 10,
			want:    []string{"hello"},
		},
		{
			name:  "two words fit",
			text:  "hello world",
			width: 20,
			want:    []string{"hello world"},
		},
		{
			name:  "two words need wrap",
			text:  "hello world",
			width: 6,
			want:    []string{"hello", "world"},
		},
		{
			name:  "multiple words wrap",
			text:  "the quick brown fox",
			width: 10,
			want:    []string{"the", "quick", "brown", "fox"},
		},
		{
			name:  "word longer than width",
			text:  "superlongword short",
			width: 5,
			want:    []string{"superlongword", "short"},
		},
		{
			name:  "collapse whitespace",
			text:  "a   b\tc\n d",
			width: 20,
			want:    []string{"a b c d"},
		},
		{
			name:  "trailing spaces trimmed",
			text:  "hello world  ",
			width: 20,
			want:    []string{"hello world"},
		},
		{
			name:  "leading spaces trimmed",
			text:  "  hello world",
			width: 20,
			want:    []string{"hello world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if !equal(got, tt.want) {
				t.Errorf("Wrap(%q, %d) = %v; want %v", tt.text, tt.width, got, tt.want)
			}
		})
	}
}

func equal(a, b []string) bool {
	if a == nil && b == nil {
		return true
	}
	if (a == nil) != (b == nil) {
		return false
	}
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

